    display_offset: float | None
    #: With a display unit: shown as value * display_scale + display_offset.
    display_scale: float | None
    display_unit: str | None
    display_unit_symbol: str | None
    #: Can be set once, and can't change after.
    immutable: bool
    #: Quantities: common units values can be given in. Any convertible UCUM unit works.
    input_units: list[UnitOption]
    #: Lists: the type of each item.
    items: str | None
    label: str
    max: float | None
    max_length: int | None
    min: float | None
    min_length: int | None
    name: str
    pattern: str | None
    #: The plugin that defines the field.
    plugin: str
    required: bool
    #: References: the type they refer to.
    to: str | None
    type: str
    #: No two entities in a project have the same value, such as a LIMS record's ID.
    unique: bool
    #: Quantities: the UCUM unit values are in.
    unit: str | None
    #: The unit as people write it, such as Å for Ao.
    unit_symbol: str | None
    #: Enums: the allowed values.
    values: list[str]


