class RunIn(TypedDict):
    #: A run reads only what's in its project (ADR 0066). Set true to add inputs from other projects to it first, which its members can then read; each is audited as `entity.linked`. Without it, such inputs are refused with 409 `inputs_outside_project`, which lists them.
    add_to_project: NotRequired[bool]
    #: Entity IDs for each input: one, or a list for inputs that take many.
    inputs: NotRequired[dict[str, str | list[str]]]
    params: NotRequired[dict[str, Any]]
    #: Where it runs. Entities it creates belong to it.
    project: str
    #: Why, for the record.
    reason: NotRequired[str]
    #: For a deterministic action: reuse the results of an identical run that succeeded, which you can read, instead of running again (ADR 0057). The run ends at once, with `reused_from`. Set false to run it anyway.
    reuse: NotRequired[bool]


class RunInputOut(TypedDict):
    entity: str
    hrid: str
    name: str
    #: The revision the run read.
    revision: int


class RunOut(TypedDict):
    action: str
    #: The agent that asked for it, acting for requested_by, if one did (ADR 0072).
    agent: AgentOut | None
    #: When an agent asked for it on a tier that needs approval: the request.
    approval: RunApprovalOut | None
    attempts: int
    #: The batch it was launched in, if any.
    batch: BatchRefOut | None
    can: RunCan
    cancel_requested_at: str | None
    #: The OAuth app it was asked for through, if any.
    client: str
    #: On the container and VM tiers: what the machines it ran on cost (ADR 0070). Null on tiers whose machines run anyway.
    cost: RunCostOut | None
    created_at: str
    #: How many entities it created, updated and reused.
    effect_counts: EffectCountsOut
    #: The first 100 entities it created, updated or reused, that you can read. `GET /runs/{ref}/effects` pages through all of them.
    effects: list[EffectOut]
    #: When it changed more than `effects` lists: the `cursor` for `GET /runs/{ref}/effects` that goes on from there.
    effects_next_cursor: str | None
    environment: str
    error: ErrorOut | None
    #: The files its file params name, by ID, that you can read.
    files: dict[str, RunFileOut]
    finished_at: str | None
    hrid: str
    id: str
    inputs: list[RunInputOut]
    messages: list[MessageOut]
    metrics: dict[str, float]
    #: A queued client-tier run whose requester has no worker online on their own computer to run it (ADR 0058): `yours` when that's you, else `theirs`.
    needs_worker: Literal['yours', 'theirs'] | None
    #: The hosts it may reach, as its action declared them when it was launched.
    network: list[str]
    params: dict[str, Any]
    #: The plugin's commit, when built from a lockfile.
    plugin_sha: str
    plugin_version: str
    project: str
    reason: str
    #: The run it reproduces exactly, if you can read it. It writes nothing.
    reproduces: RunRefOut | None
    #: Once a reproduction has its results: whether they match the original's.
    reproduction: ReproductionOut | None
    requested_by: PersonRef
    #: It reused an identical run's results, and ran nothing (ADR 0057).
    reused: bool
    #: The run whose results it reused, if you can read it.
    reused_from: RunRefOut | None
    #: The seed its command was given (`IKI_SEED`). None for runs from before seeds.
    seed: int | None
    #: The plugin's settings, as the deployment set them when it was launched.
    settings: dict[str, Any]
    started_at: str | None
    status: Literal['awaiting_approval', 'queued', 'running', 'succeeded', 'failed', 'cancelled', 'timed_out', 'rejected', 'declined']
    tier: Literal['client', 'backend', 'container', 'vm']
    #: The project's trigger that launched it, if one did, and the change or schedule that fired it (ADR 0080).
    trigger: TriggerFiredOut | None
    via: str
    #: Why a queued run hasn't started: a quota is holding it, or the machine being started for it is waiting (for a node with a GPU, say).
    waiting: str | None
    #: The workflow run it's a step of, if any (ADR 0079).
    workflow: WorkflowStepRefOut | None


class RunRefOut(TypedDict):
    action: str
    hrid: str
    id: str


RunStatus = Literal['awaiting_approval', 'queued', 'running', 'succeeded', 'failed', 'cancelled', 'timed_out', 'rejected', 'declined']


